/* ===== js/loader.js ===== */
(function () {
  var loader = $('#loader');
  var bar = $('.ld-bar i');
  var startTime = performance.now();
  var duration = reduced ? 0 : 1200;
  var finished = false;

  function finish() {
    if (finished) return;
    finished = true;
    loader.classList.add('done');
    document.body.classList.add('ready');
    setTimeout(function () { loader.remove(); }, 900);
  }

  function tick(now) {
    var elapsed = (now || performance.now()) - startTime;
    var progress = duration ? Math.min(1, elapsed / duration) : 1;
    bar.style.width = (progress * 100) + '%';

    var pageLoaded = document.readyState === 'complete';
    if (progress >= 1 && (pageLoaded || elapsed > 3500)) {
      finish();
    } else {
      requestAnimationFrame(tick);
    }
  }

  tick(startTime);
  setTimeout(finish, 5000);
})();

;

/* ===== js/background.js ===== */
(function () {
  var canvas = $('#gl');
  var image = $('#bgsrc');
  var staysStill = !FORCE_MOTION && matchMedia('(prefers-reduced-motion: reduce)').matches;
  var gl = canvas.getContext('webgl', { antialias: false, alpha: true }) ||
           canvas.getContext('experimental-webgl');

  image.src = window.BG_DATA;
  $('.bg-img').style.backgroundImage = 'url(' + image.src + ')';

  function useFallback(reason) {
    if (reason) console.warn('Nền WebGL tắt, dùng ảnh tĩnh:', reason);
    canvas.style.display = 'none';
  }

  if (!gl) { useFallback('không tạo được WebGL'); return; }

  var VERTEX_SHADER = 'attribute vec2 p;void main(){gl_Position=vec4(p,0.,1.);}';

  var FRAGMENT_SHADER = [
    '#ifdef GL_FRAGMENT_PRECISION_HIGH', 'precision highp float;', '#else', 'precision mediump float;', '#endif',
    'uniform sampler2D uTex,uFlow,uAct;uniform vec2 uRes,uImg,uMouse;uniform float uT,uVel;',
    'const float A=1.136;',
    'vec2 rot(vec2 d,float a){float c=cos(a),s=sin(a);return vec2(c*d.x-s*d.y,s*d.x+c*d.y);}',
    'vec2 swirl(vec2 uv,vec2 c,float r,float s,float ph){',
    ' vec2 d=uv-c;d.x*=A;float w=exp(-dot(d,d)/(r*r));',
    ' float a=s*w*(0.6+0.9*sin(uT*0.3+ph));d=rot(d,a);d.x/=A;return c+d-uv;}',
    'float glow(vec2 uv,vec2 c,float r,float ph){vec2 d=uv-c;d.x*=A;',
    ' return exp(-dot(d,d)/(r*r))*(0.5+0.5*sin(uT*0.9+ph));}',
    'void main(){',
    ' vec2 f=vec2(gl_FragCoord.x,uRes.y-gl_FragCoord.y);',
    ' float act=smoothstep(0.0,0.85,texture2D(uAct,vec2(gl_FragCoord.x/uRes.x,1.0-gl_FragCoord.y/uRes.y)).r);',
    ' vec2 d=f-uMouse;float R=0.16*max(uRes.x,uRes.y);',
    ' float w=exp(-dot(d,d)/(R*R));',
    ' f=uMouse+rot(d,w*uVel*(0.2+0.16*sin(uT*0.6)));',
    ' vec2 ax=uRes/uImg;float cv=max(ax.x,ax.y);',
    ' vec2 sc=mix(vec2(cv),ax,0.75);',
    ' sc.x=max(sc.x,sc.y/1.35);sc.y=max(sc.y,sc.x/1.35);sc=max(sc,ax)*1.03;',
    ' vec2 uv=(f-0.5*uRes)/(uImg*sc)+0.5;',
    ' float m=1.0-smoothstep(0.70,0.88,uv.y);',
    ' vec2 q=uv;',
    ' q+=m*act*(swirl(uv,vec2(0.55,0.33),0.30,0.30,0.0)+swirl(uv,vec2(0.60,0.52),0.12,0.55,0.7)+swirl(uv,vec2(0.08,0.21),0.10,0.7,2.0)',
    '   +swirl(uv,vec2(0.83,0.48),0.12,0.55,1.3)+swirl(uv,vec2(0.355,0.595),0.08,0.6,3.0)+swirl(uv,vec2(0.68,0.60),0.07,0.6,4.0)',
    '   +swirl(uv,vec2(0.63,0.667),0.08,0.6,5.0));',
    ' q+=m*act*0.005*vec2(sin(uv.y*14.0+uT*0.3+sin(uv.x*6.0)),cos(uv.x*12.0-uT*0.25));',
    ' vec2 e=texture2D(uFlow,uv).rg*2.0-1.0;',
    ' float coh=length(e);vec2 dir=vec2(cos(atan(e.y,e.x+1e-4)*0.5),sin(atan(e.y,e.x+1e-4)*0.5));',
    ' float amp=0.012*act*(0.35+0.65*m)*smoothstep(0.04,0.3,coh);',
    ' float p0=fract(uT*0.16),p1=fract(uT*0.16+0.5);',
    ' float w0=1.0-abs(2.0*p0-1.0);',
    ' vec3 c0=texture2D(uTex,q-dir*p0*amp).rgb;vec3 c1=texture2D(uTex,q-dir*p1*amp).rgb;',
    ' vec3 c=mix(c1,c0,w0);',
    ' float g=glow(q,vec2(0.60,0.52),0.05,0.0)+glow(q,vec2(0.08,0.21),0.04,1.5)+glow(q,vec2(0.83,0.48),0.045,3.0)',
    '  +glow(q,vec2(0.355,0.595),0.035,4.5)+glow(q,vec2(0.68,0.60),0.03,2.2)+glow(q,vec2(0.63,0.667),0.035,5.2);',
    ' c+=vec3(1.0,0.78,0.25)*g*0.28*act;',
    ' gl_FragColor=vec4(c*0.92,1.0);}'
  ].join('\n');

  function compileShader(type, source) {
    var shader = gl.createShader(type);
    gl.shaderSource(shader, source);
    gl.compileShader(shader);
    if (gl.getShaderParameter(shader, gl.COMPILE_STATUS)) return shader;
    console.warn('Lỗi shader:', gl.getShaderInfoLog(shader));
    return null;
  }

  var vertexShader = compileShader(gl.VERTEX_SHADER, VERTEX_SHADER);
  var fragmentShader = compileShader(gl.FRAGMENT_SHADER, FRAGMENT_SHADER);
  if (!vertexShader || !fragmentShader) { useFallback(); return; }

  var program = gl.createProgram();
  gl.attachShader(program, vertexShader);
  gl.attachShader(program, fragmentShader);
  gl.linkProgram(program);
  if (!gl.getProgramParameter(program, gl.LINK_STATUS)) {
    useFallback(gl.getProgramInfoLog(program));
    return;
  }
  gl.useProgram(program);

  var quad = gl.createBuffer();
  gl.bindBuffer(gl.ARRAY_BUFFER, quad);
  gl.bufferData(gl.ARRAY_BUFFER, new Float32Array([-1, -1, 1, -1, -1, 1, 1, 1]), gl.STATIC_DRAW);
  var positionLocation = gl.getAttribLocation(program, 'p');
  gl.enableVertexAttribArray(positionLocation);
  gl.vertexAttribPointer(positionLocation, 2, gl.FLOAT, false, 0, 0);

  var uniform = {};
  ['uTex', 'uFlow', 'uAct', 'uRes', 'uImg', 'uMouse', 'uT', 'uVel'].forEach(function (name) {
    uniform[name] = gl.getUniformLocation(program, name);
  });

  var GRID_W = 160, gridH = 90;
  var activity = new Float32Array(GRID_W * gridH);
  var activitySmooth = new Float32Array(GRID_W * gridH);
  var activityBytes = new Uint8Array(GRID_W * gridH);
  var hasActivity = false;
  var needsRedraw = true;

  var width, height;
  var mouseX = -9999, mouseY = -9999;
  var smoothX = -9999, smoothY = -9999;
  var velocity = 0;
  var pointerInside = false;
  var presence = 0;
  var lastX = null, lastY = null;
  var startTime = performance.now();

  function resize() {
    var ratio = Math.min(devicePixelRatio || 1, 1.5);
    width = canvas.width = Math.round(innerWidth * ratio);
    height = canvas.height = Math.round(innerHeight * ratio);
    gl.viewport(0, 0, width, height);

    gridH = Math.max(8, Math.round(GRID_W * innerHeight / innerWidth));
    activity = new Float32Array(GRID_W * gridH);
    activitySmooth = new Float32Array(GRID_W * gridH);
    activityBytes = new Uint8Array(GRID_W * gridH);
    hasActivity = false;
    needsRedraw = true;
  }
  resize();
  addEventListener('resize', resize);

  function splat(nx, ny, strength) {
    var cx = nx * GRID_W, cy = ny * gridH;
    var radius = GRID_W * 0.11;
    var x0 = Math.max(0, Math.floor(cx - radius * 2));
    var x1 = Math.min(GRID_W - 1, Math.ceil(cx + radius * 2));
    var y0 = Math.max(0, Math.floor(cy - radius * 2));
    var y1 = Math.min(gridH - 1, Math.ceil(cy + radius * 2));

    for (var y = y0; y <= y1; y++) {
      for (var x = x0; x <= x1; x++) {
        var dx = x - cx, dy = y - cy;
        var add = strength * Math.exp(-(dx * dx + dy * dy) / (radius * radius));
        var i = y * GRID_W + x;
        activity[i] = Math.min(1, activity[i] + add);
      }
    }
    hasActivity = true;
  }

  function onPointerMove(e) {
    var ratio = Math.min(devicePixelRatio || 1, 1.5);
    var x = e.clientX * ratio, y = e.clientY * ratio;

    if (lastX !== null) velocity = Math.min(1, Math.max(velocity, Math.hypot(x - lastX, y - lastY) / (60 * ratio)));
    if (smoothX < -999) { smoothX = x; smoothY = y; }

    if (!staysStill) {
      var fromX = lastX === null ? x : lastX;
      var fromY = lastX === null ? y : lastY;
      var distance = Math.hypot(x - fromX, y - fromY);
      var stepSize = 0.03 * width;
      var steps = Math.max(1, Math.ceil(distance / stepSize));
      var strength = 0.09 * Math.min(1, distance / (steps * stepSize));

      if (distance > 0.5) {
        for (var i = 1; i <= steps; i++) {
          splat((fromX + (x - fromX) * i / steps) / width, (fromY + (y - fromY) * i / steps) / height, strength);
        }
      }
    }

    mouseX = x; mouseY = y;
    lastX = x; lastY = y;
    pointerInside = true;
  }

  addEventListener('pointermove', onPointerMove, { passive: true });
  addEventListener('mousemove', onPointerMove, { passive: true });
  document.documentElement.addEventListener('mouseenter', function () { pointerInside = true; });
  document.documentElement.addEventListener('mouseleave', function () { pointerInside = false; });
  addEventListener('blur', function () { pointerInside = false; });
  addEventListener('pointerup', function (e) { if (e.pointerType !== 'mouse') pointerInside = false; }, { passive: true });

  function boxBlur(data, N, r) {
    var temp = new Float32Array(N * N);
    var inv = 1 / (2 * r + 1);
    var x, y, k, sum, row;
    function clampIndex(v) { return v < 0 ? 0 : v > N - 1 ? N - 1 : v; }

    for (y = 0; y < N; y++) {
      row = y * N; sum = 0;
      for (k = -r; k <= r; k++) sum += data[row + clampIndex(k)];
      for (x = 0; x < N; x++) {
        temp[row + x] = sum * inv;
        sum += data[row + clampIndex(x + r + 1)] - data[row + clampIndex(x - r)];
      }
    }
    for (x = 0; x < N; x++) {
      sum = 0;
      for (k = -r; k <= r; k++) sum += temp[clampIndex(k) * N + x];
      for (y = 0; y < N; y++) {
        data[y * N + x] = sum * inv;
        sum += temp[clampIndex(y + r + 1) * N + x] - temp[clampIndex(y - r) * N + x];
      }
    }
  }

  function buildFlowMap(N) {
    var small = document.createElement('canvas');
    small.width = small.height = N;
    var smallCtx = small.getContext('2d');
    smallCtx.drawImage(image, 0, 0, N, N);
    var pixels = smallCtx.getImageData(0, 0, N, N).data;
    var gray = new Float32Array(N * N);
    var i, x, y;
    for (i = 0; i < N * N; i++) {
      gray[i] = (0.299 * pixels[4 * i] + 0.587 * pixels[4 * i + 1] + 0.114 * pixels[4 * i + 2]) / 255;
    }

    var xx = new Float32Array(N * N), yy = new Float32Array(N * N), xy = new Float32Array(N * N);
    for (y = 1; y < N - 1; y++) {
      for (x = 1; x < N - 1; x++) {
        i = y * N + x;
        var gx = (gray[i - N + 1] + 2 * gray[i + 1] + gray[i + N + 1]) - (gray[i - N - 1] + 2 * gray[i - 1] + gray[i + N - 1]);
        var gy = (gray[i + N - 1] + 2 * gray[i + N] + gray[i + N + 1]) - (gray[i - N - 1] + 2 * gray[i - N] + gray[i - N + 1]);
        xx[i] = gx * gx; yy[i] = gy * gy; xy[i] = gx * gy;
      }
    }
    [xx, yy, xy].forEach(function (channel) { boxBlur(channel, N, 5); boxBlur(channel, N, 5); });

    var out = new Uint8Array(N * N * 4);
    for (i = 0; i < N * N; i++) {
      var s = xx[i] + yy[i] + 1e-6;
      var weight = Math.min(1, s / 0.04);
      var ex = -(xx[i] - yy[i]) / s * weight;
      var ey = -2 * xy[i] / s * weight;
      out[4 * i]     = Math.max(0, Math.min(255, Math.round((ex * 0.5 + 0.5) * 255)));
      out[4 * i + 1] = Math.max(0, Math.min(255, Math.round((ey * 0.5 + 0.5) * 255)));
      out[4 * i + 2] = 0;
      out[4 * i + 3] = 255;
    }
    return out;
  }

  function createTexture(unit) {
    var texture = gl.createTexture();
    gl.activeTexture(gl.TEXTURE0 + unit);
    gl.bindTexture(gl.TEXTURE_2D, texture);
    gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MIN_FILTER, gl.LINEAR);
    gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MAG_FILTER, gl.LINEAR);
    gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_WRAP_S, gl.CLAMP_TO_EDGE);
    gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_WRAP_T, gl.CLAMP_TO_EDGE);
    return texture;
  }

  function uploadActivity() {
    gl.activeTexture(gl.TEXTURE2);
    gl.texImage2D(gl.TEXTURE_2D, 0, gl.LUMINANCE, GRID_W, gridH, 0, gl.LUMINANCE, gl.UNSIGNED_BYTE, activityBytes);
  }

  function start() {
    try { startRendering(); } catch (e) { useFallback(e && e.message); }
  }

  function startRendering() {
    createTexture(0);
    var big = document.createElement('canvas');
    big.width = big.height = 2048;
    big.getContext('2d').drawImage(image, 0, 0, 2048, 2048);
    gl.texImage2D(gl.TEXTURE_2D, 0, gl.RGBA, gl.RGBA, gl.UNSIGNED_BYTE, big);

    createTexture(1);
    var FLOW_SIZE = 512;
    gl.texImage2D(gl.TEXTURE_2D, 0, gl.RGBA, FLOW_SIZE, FLOW_SIZE, 0, gl.RGBA, gl.UNSIGNED_BYTE, buildFlowMap(FLOW_SIZE));

    createTexture(2);
    gl.pixelStorei(gl.UNPACK_ALIGNMENT, 1);

    gl.uniform1i(uniform.uTex, 0);
    gl.uniform1i(uniform.uFlow, 1);
    gl.uniform1i(uniform.uAct, 2);
    gl.uniform2f(uniform.uImg, image.naturalWidth, image.naturalHeight);

    var lastFrame = performance.now();

    (function loop() {
      requestAnimationFrame(loop);
      var now = performance.now();
      var dt = Math.min(0.1, Math.max(0.001, (now - lastFrame) / 1000));
      lastFrame = now;

      try {
        smoothX += (mouseX - smoothX) * (1 - Math.exp(-dt * 3.2));
        smoothY += (mouseY - smoothY) * (1 - Math.exp(-dt * 3.2));
        velocity *= Math.exp(-dt * 3.5);
        presence += ((pointerInside && !staysStill ? 1 : 0) - presence) * (1 - Math.exp(-dt * 2.2));
        if (presence < 0.002 && !pointerInside) presence = 0;

        if (pointerInside && !staysStill) splat(mouseX / width, mouseY / height, 0.3 * dt);

        var shouldDraw = hasActivity || velocity > 0.002 || presence > 0 || needsRedraw;

        if (hasActivity) {
          var fade = Math.exp(-dt / 2.6);
          var smooth = 1 - Math.exp(-dt * 2.2);
          var anyLeft = false;
          for (var i = 0; i < activity.length; i++) {
            var value = activity[i] * fade;
            if (value < 0.0003) value = 0;
            activity[i] = value;

            var smoothed = activitySmooth[i] + (value - activitySmooth[i]) * smooth;
            if (smoothed < 0.0003 && value === 0) smoothed = 0; else anyLeft = true;
            activitySmooth[i] = smoothed;
            activityBytes[i] = Math.min(255, Math.round(smoothed * 255));
          }
          hasActivity = anyLeft;
          uploadActivity();
        } else if (needsRedraw) {
          uploadActivity();
        }

        if (shouldDraw) {
          gl.uniform2f(uniform.uRes, width, height);
          gl.uniform2f(uniform.uMouse, smoothX, smoothY);
          gl.uniform1f(uniform.uT, (now - startTime) / 1000);
          gl.uniform1f(uniform.uVel, presence);
          gl.drawArrays(gl.TRIANGLE_STRIP, 0, 4);
          needsRedraw = hasActivity || velocity > 0.002 || presence > 0;
          if (gl.isContextLost()) useFallback('mất ngữ cảnh WebGL');
        }
      } catch (err) {
        console.warn('Lỗi vòng lặp nền:', err && err.message);
      }
    })();
  }

  if (image.complete && image.naturalWidth) {
    start();
  } else {
    image.onload = start;
    image.onerror = function () { useFallback('ảnh nền không tải được'); };
  }
})();

;

/* ===== js/nav.js ===== */
(function () {
  var nav = $('nav');
  var burger = $('#burger');

  function setOpen(open) {
    nav.classList.toggle('open', open);
    burger.setAttribute('aria-expanded', open);
    burger.setAttribute('aria-label', open ? 'Đóng menu' : 'Mở menu');
  }

  burger.addEventListener('click', function () {
    setOpen(!nav.classList.contains('open'));
  });

  $('#menu').addEventListener('click', function (e) {
    if (e.target.closest('a')) setOpen(false);
  });
  addEventListener('keydown', function (e) {
    if (e.key === 'Escape') setOpen(false);
  });

  var linkById = {};
  $$('#menu a').forEach(function (link) {
    linkById[link.getAttribute('href').slice(1)] = link;
  });

  var observer = new IntersectionObserver(function (entries) {
    entries.forEach(function (entry) {
      if (!entry.isIntersecting) return;
      Object.keys(linkById).forEach(function (id) { linkById[id].classList.remove('act'); });
      var current = linkById[entry.target.id];
      if (current) current.classList.add('act');
    });
  }, { rootMargin: '-45% 0px -50% 0px' });

  Object.keys(linkById).forEach(function (id) {
    var section = document.getElementById(id);
    if (section) observer.observe(section);
  });
})();

;

/* ===== js/smooth-scroll.js ===== */
(function () {
  var MIN_DURATION = 700;   // thời gian cuộn tối thiểu (ms)
  var MAX_DURATION = 1500;  // thời gian cuộn tối đa (ms)
  var MS_PER_PIXEL = 0.6;   // đi càng xa thì cuộn càng lâu

  var frameId = null;

  // Bắt đầu chậm, giữa nhanh, cuối chậm dần
  function easeInOutCubic(t) {
    return t < 0.5 ? 4 * t * t * t : 1 - Math.pow(-2 * t + 2, 3) / 2;
  }

  // Khoảng chừa cho thanh menu cố định phía trên (lấy từ scroll-padding-top trong CSS)
  function headerOffset() {
    return parseFloat(getComputedStyle(document.documentElement).scrollPaddingTop) || 0;
  }

  function stop() {
    if (frameId) cancelAnimationFrame(frameId);
    frameId = null;
  }

  function scrollToY(targetY) {
    stop();

    var maxY = document.documentElement.scrollHeight - innerHeight;
    var endY = Math.max(0, Math.min(targetY, maxY));
    var startY = window.scrollY;
    var distance = endY - startY;

    if (reduced || !distance) {
      window.scrollTo(0, endY);
      return;
    }

    var duration = Math.min(MAX_DURATION, Math.max(MIN_DURATION, Math.abs(distance) * MS_PER_PIXEL));
    var startTime = performance.now();

    function step(now) {
      var progress = Math.min(1, (now - startTime) / duration);
      window.scrollTo(0, startY + distance * easeInOutCubic(progress));
      frameId = progress < 1 ? requestAnimationFrame(step) : null;
    }
    frameId = requestAnimationFrame(step);
  }

  // Cho file khác (nút lên đầu trang) dùng chung
  window.scrollToY = scrollToY;

  // Bấm vào bất kỳ liên kết #mục nào cũng cuộn mượt tới đó
  document.addEventListener('click', function (e) {
    var link = e.target.closest('a[href^="#"]');
    if (!link) return;

    var id = decodeURIComponent(link.getAttribute('href').slice(1));
    var target = id && document.getElementById(id);
    if (!target) return;

    e.preventDefault();
    var y = id === 'top' ? 0 : target.getBoundingClientRect().top + window.scrollY - headerOffset();
    scrollToY(y);
    history.replaceState(history.state, '', '#' + id);
  });

  // Người dùng tự cuộn thì dừng hiệu ứng, không giành quyền điều khiển
  ['wheel', 'touchstart', 'keydown'].forEach(function (type) {
    addEventListener(type, stop, { passive: true });
  });
})();

;

/* ===== js/frame.js ===== */
(function () {
  const STAYS_WHERE_DROPPED = false;

  const WIRE_LENGTH = 130;
  const NAIL_Y = 16;
  const SPRING = 30;
  const FRICTION = 3.2;
  const KEY_PUSH = 700;
  const MAX_TILT = 0.6;
  const SVG_NS = 'http://www.w3.org/2000/svg';

  const area = $('#lan');
  const frame = $('#hang');
  if (!area || !frame) return;

  const wireLeft = createWire();
  const wireRight = createWire();
  frame.style.top = WIRE_LENGTH + 'px';

  let x = 0, y = 0;
  let velocityX = 0, velocityY = 0;
  let targetX = 0, targetY = 0;
  let grabOffsetX = 0, grabOffsetY = 0;
  let wobble = 0;
  let dragging = false;
  let running = false;
  let lastTime = 0;
  let areaWidth, areaHeight, frameWidth, frameHeight;
  let limitX, limitTop, limitBottom, restWireLength;

  function createWire() {
    const path = document.createElementNS(SVG_NS, 'path');
    return path;
  }

  const svg = document.createElementNS(SVG_NS, 'svg');
  svg.setAttribute('class', 'wire-svg');
  svg.setAttribute('aria-hidden', 'true');
  svg.appendChild(wireLeft);
  svg.appendChild(wireRight);
  area.insertBefore(svg, area.firstChild);

  function clamp(value, min, max) {
    return Math.min(max, Math.max(min, value));
  }

  function measure() {
    areaWidth = area.clientWidth;
    areaHeight = area.clientHeight;
    frameWidth = frame.offsetWidth;
    frameHeight = frame.offsetHeight;
    limitX = Math.max(0, (areaWidth - frameWidth) / 2 - 4);
    limitTop = -(WIRE_LENGTH - 46);
    limitBottom = Math.max(0, areaHeight - WIRE_LENGTH - frameHeight - 34);
    restWireLength = Math.hypot(frameWidth / 2 - 4, WIRE_LENGTH + 4 - NAIL_Y);
  }

  function drawWire(path, fromX, fromY, toX, toY) {
    const slack = Math.max(0, restWireLength - Math.hypot(toX - fromX, toY - fromY)) * 1.1;
    const midX = (fromX + toX) / 2;
    const midY = (fromY + toY) / 2 + slack;
    path.setAttribute('d', 'M' + fromX.toFixed(1) + ' ' + fromY + 'Q' + midX.toFixed(1) + ' ' + midY.toFixed(1) + ' ' + toX.toFixed(1) + ' ' + toY.toFixed(1));
  }

  function draw(now) {
    const idleSway = reduced ? 0 : 0.018 * Math.sin((now || 0) / 1300);
    const pendulum = -Math.atan2(x, WIRE_LENGTH + y - NAIL_Y) * 0.55;
    const angle = clamp(pendulum + wobble + idleSway, -MAX_TILT, MAX_TILT);

    frame.style.transform =
      'translateX(calc(-50% + ' + x.toFixed(2) + 'px)) translateY(' + y.toFixed(2) + 'px) rotate(' + angle.toFixed(4) + 'rad)';

    const centerX = areaWidth / 2 + x;
    const topY = WIRE_LENGTH + y;
    const halfSpan = frameWidth / 2 - 4;
    const cos = Math.cos(angle);
    const sin = Math.sin(angle);
    const nailX = areaWidth / 2;

    drawWire(wireLeft, nailX, NAIL_Y, centerX - halfSpan * cos - 4 * sin, topY - halfSpan * sin + 4 * cos);
    drawWire(wireRight, nailX, NAIL_Y, centerX + halfSpan * cos - 4 * sin, topY + halfSpan * sin + 4 * cos);
  }

  function bounceOffLimits() {
    if (x > limitX) { x = limitX; velocityX *= -0.3; }
    else if (x < -limitX) { x = -limitX; velocityX *= -0.3; }
    if (y > limitBottom) { y = limitBottom; velocityY *= -0.3; }
    else if (y < limitTop) { y = limitTop; velocityY *= -0.3; }
  }

  function step(now) {
    const dt = Math.min(0.033, (now - lastTime) / 1000) || 0.016;
    lastTime = now;
    const previousX = x, previousY = y;

    if (dragging) {
      const follow = 1 - Math.exp(-dt * 28);
      x += (targetX - x) * follow;
      y += (targetY - y) * follow;
      velocityX = velocityX * 0.6 + ((x - previousX) / dt) * 0.4;
      velocityY = velocityY * 0.6 + ((y - previousY) / dt) * 0.4;
    } else {
      if (STAYS_WHERE_DROPPED) {
        velocityX *= Math.exp(-dt * 3);
        velocityY *= Math.exp(-dt * 3);
      } else {
        velocityX += (-SPRING * x - FRICTION * velocityX) * dt;
        velocityY += (-SPRING * y - FRICTION * velocityY) * dt;
      }
      x += velocityX * dt;
      y += velocityY * dt;
      bounceOffLimits();
    }

    const lag = clamp(velocityX * 0.00045, -0.35, 0.35);
    wobble += (lag - wobble) * (1 - Math.exp(-dt * 7));

    draw(now);
    if (running) requestAnimationFrame(step);
  }

  function run() {
    if (running || reduced) return;
    running = true;
    lastTime = performance.now();
    requestAnimationFrame(step);
  }

  function stop() {
    running = false;
  }

  function release() {
    if (!dragging) return;
    dragging = false;
    frame.classList.remove('drag');
    velocityX = clamp(velocityX, -2500, 2500);
    velocityY = clamp(velocityY, -2500, 2500);
    if (reduced && !STAYS_WHERE_DROPPED) {
      x = y = 0;
      draw(0);
    }
  }

  frame.addEventListener('pointerdown', function (e) {
    measure();
    dragging = true;
    frame.classList.add('drag');
    frame.setPointerCapture(e.pointerId);
    grabOffsetX = e.clientX - x;
    grabOffsetY = e.clientY - y;
    targetX = x;
    targetY = y;
    run();
    e.preventDefault();
  });

  frame.addEventListener('pointermove', function (e) {
    if (!dragging) return;
    targetX = clamp(e.clientX - grabOffsetX, -limitX, limitX);
    targetY = clamp(e.clientY - grabOffsetY, limitTop, limitBottom);
    if (reduced) {
      x = targetX;
      y = targetY;
      draw(0);
    }
  });

  frame.addEventListener('pointerup', release);
  frame.addEventListener('pointercancel', release);

  const KEY_DIRECTIONS = {
    ArrowLeft: [-1, 0],
    ArrowRight: [1, 0],
    ArrowUp: [0, -1],
    ArrowDown: [0, 1]
  };

  frame.addEventListener('keydown', function (e) {
    const direction = KEY_DIRECTIONS[e.key];
    if (!direction) return;
    e.preventDefault();
    measure();

    if (reduced) {
      x = clamp(x + direction[0] * 40, -limitX, limitX);
      y = clamp(y + direction[1] * 40, limitTop, limitBottom);
      draw(0);
      return;
    }
    velocityX += direction[0] * KEY_PUSH;
    velocityY += direction[1] * KEY_PUSH;
    run();
  });

  addEventListener('resize', function () {
    measure();
    x = clamp(x, -limitX, limitX);
    y = clamp(y, limitTop, limitBottom);
    draw(performance.now());
  });

  new IntersectionObserver(function (entries) {
    if (entries[0].isIntersecting) run(); else stop();
  }, { threshold: 0 }).observe(area);

  measure();
  draw(0);
})();

;

/* ===== js/reveal.js ===== */
(function () {
  var SHOW_RATIO = 0.12;     // phần khối lộ ra bao nhiêu thì bắt đầu hiện
  var STAGGER_STEP = 0.12;   // độ trễ giữa các khối cùng hàng (giây)

  function countUp(el) {
    var target = Number(el.dataset.n) || 0;
    var suffix = el.dataset.s || '';
    var startTime = performance.now();

    if (reduced || !target) {
      el.textContent = target + suffix;
      return;
    }

    (function step(now) {
      var progress = Math.min(1, (now - startTime) / 1200);
      var eased = 1 - Math.pow(1 - progress, 3);
      el.textContent = Math.round(target * eased) + suffix;
      if (progress < 1) requestAnimationFrame(step);
    })(startTime);
  }

  window.animateBars = function (root) {
    requestAnimationFrame(function () {
      requestAnimationFrame(function () {
        $$('.bar', root).forEach(function (bar) { bar.classList.add('go'); });
      });
    });
  };

  function show(block) {
    block.classList.add('on');
    $$('[data-n]', block).forEach(countUp);
    window.animateBars(block);
  }

  // Ẩn lại khi ra khỏi màn hình để lần cuộn sau (lên hoặc xuống) hiện lại từ đầu
  function hide(block) {
    block.classList.remove('on');
    $$('.bar', block).forEach(function (bar) { bar.classList.remove('go'); });
  }

  // Các khối cùng cha hiện lần lượt thay vì cùng lúc
  $$('.fade').forEach(function (el) {
    var index = $$('.fade', el.parentElement).indexOf(el);
    el.style.setProperty('--delay', (index * STAGGER_STEP).toFixed(2) + 's');
  });

  var observer = new IntersectionObserver(function (entries) {
    entries.forEach(function (entry) {
      if (entry.isIntersecting && entry.intersectionRatio >= SHOW_RATIO) show(entry.target);
      else if (!entry.isIntersecting) hide(entry.target);
    });
  }, { threshold: [0, SHOW_RATIO] });

  $$('.fade').forEach(function (el) { observer.observe(el); });
})();

;

/* ===== js/tabs.js ===== */
(function () {
  var ALL = 'Tất cả';

  $$('.tabs').forEach(function (tabs) {
    var list = $(tabs.dataset.target);
    if (!list) return;

    var buttons = $$('button', tabs);
    var items = $$('[data-cat]', list);

    function applyFilter(category) {
      buttons.forEach(function (button) {
        var selected = button.dataset.filter === category;
        button.classList.toggle('on', selected);
        button.setAttribute('aria-selected', selected);
      });

      items.forEach(function (item) {
        var visible = category === ALL || item.dataset.cat === category;
        item.hidden = !visible;
        if (visible && item.resetPaint) item.resetPaint();
      });

      $$('.bar', list).forEach(function (bar) { bar.classList.remove('go'); });
      window.animateBars(list);
    }

    tabs.addEventListener('click', function (e) {
      var button = e.target.closest('button');
      if (button) applyFilter(button.dataset.filter);
    });
  });
})();

;

/* ===== js/project-modal.js ===== */
(function () {
  var modal = $('#detail');
  var cards = $$('.card[data-project]');
  var lastFocused = null;

  function indexOfProject(id) {
    for (var i = 0; i < cards.length; i++) {
      if (cards[i].dataset.project === id) return i;
    }
    return -1;
  }

  function titleOf(card) {
    return $('h3', card).textContent;
  }

  function makeButton(label, onClick) {
    var button = document.createElement('button');
    button.className = 'back';
    button.textContent = label;
    button.addEventListener('click', onClick);
    return button;
  }

  function render(i) {
    var card = cards[i];
    var inner = document.createElement('div');
    inner.className = 'detail-in';

    inner.appendChild(makeButton('← Quay lại dự án', closeProject));
    inner.appendChild($('template', card).content.cloneNode(true));

    var pager = document.createElement('div');
    pager.className = 'pn';
    pager.appendChild(i > 0
      ? makeButton('← ' + titleOf(cards[i - 1]), function () { openProject(cards[i - 1].dataset.project, false, true); })
      : document.createElement('span'));
    pager.appendChild(i < cards.length - 1
      ? makeButton(titleOf(cards[i + 1]) + ' →', function () { openProject(cards[i + 1].dataset.project, false, true); })
      : document.createElement('span'));
    inner.appendChild(pager);

    modal.innerHTML = '';
    modal.appendChild(inner);
    modal.scrollTop = 0;
  }

  function show(id) {
    var i = indexOfProject(id);
    if (i < 0) { hide(); return; }

    if (modal.hidden) lastFocused = document.activeElement;
    render(i);
    modal.hidden = false;
    document.documentElement.classList.add('lock');
    document.body.classList.add('lock');
    $('.back', modal).focus({ preventScroll: true });
  }

  function hide() {
    if (modal.hidden) return;
    modal.hidden = true;
    document.documentElement.classList.remove('lock');
    document.body.classList.remove('lock');
    if (lastFocused && lastFocused.focus) lastFocused.focus({ preventScroll: true });
  }

  function openProject(id, push, replace) {
    if (push) history.pushState({ project: id }, '', '#du-an/' + id);
    else if (replace) history.replaceState({ project: id }, '', '#du-an/' + id);
    show(id);
  }

  function closeProject() {
    if (history.state && history.state.project) history.back();
    else hide();
  }

  cards.forEach(function (card) {
    card.addEventListener('click', function () { openProject(card.dataset.project, true); });
    card.addEventListener('keydown', function (e) {
      if (e.key === 'Enter' || e.key === ' ') {
        e.preventDefault();
        openProject(card.dataset.project, true);
      }
    });
  });

  function projectIdFromHash() {
    var match = /^#du-an\/(.+)$/.exec(location.hash);
    return match ? decodeURIComponent(match[1]) : null;
  }

  addEventListener('popstate', function () {
    var id = projectIdFromHash();
    if (id) show(id); else hide();
  });

  addEventListener('keydown', function (e) {
    if (e.key === 'Escape' && !modal.hidden) closeProject();
  });

  var initialId = projectIdFromHash();
  if (initialId) show(initialId);
})();

;

/* ===== js/paint-reveal.js ===== */
(function () {
  var tip = $('#project-tip');

  if (!finePointer) {
    $$('.paint-layer').forEach(function (layer) { layer.style.display = 'none'; });
    if (tip) tip.textContent = '✦ Chạm vào mỗi thẻ để xem chi tiết dự án ✦';
    return;
  }

  var PAINT_COLORS = ['#1e3a8a', '#2a4a9a', '#0f1e4a', '#f9d71c', '#f5e6a8', '#8ab4f8'];
  var BRUSH_RADIUS = 34;
  var COVER_OPACITY = 0.82;
  var CLEAR_RATIO = 0.8;

  $$('[data-reveal]').forEach(function (card) {
    var canvas = $('.paint-layer', card);
    var ctx = canvas.getContext('2d');
    var lastX = null, lastY = null;
    var moveCount = 0;
    var cleared = false;

    function paintCover() {
      if (cleared) return;

      var rect = card.getBoundingClientRect();
      var ratio = devicePixelRatio || 1;
      var w = rect.width, h = rect.height;
      if (!w || !h) return;

      canvas.width = w * ratio;
      canvas.height = h * ratio;
      ctx.setTransform(ratio, 0, 0, ratio, 0, 0);
      ctx.globalCompositeOperation = 'source-over';

      var gradient = ctx.createLinearGradient(0, 0, w, h);
      gradient.addColorStop(0, '#0a1128');
      gradient.addColorStop(0.5, '#142a5e');
      gradient.addColorStop(1, '#0a1128');
      ctx.fillStyle = gradient;
      ctx.globalAlpha = COVER_OPACITY;
      ctx.fillRect(0, 0, w, h);

      for (var i = 0; i < 90; i++) {
        var x = Math.random() * w;
        var y = Math.random() * h;
        var length = 30 + Math.random() * 80;
        var angle = Math.random() * 6.28;

        ctx.strokeStyle = PAINT_COLORS[Math.random() * PAINT_COLORS.length | 0];
        ctx.globalAlpha = 0.2 + Math.random() * 0.4;
        ctx.lineWidth = 2 + Math.random() * 6;
        ctx.lineCap = 'round';
        ctx.beginPath();
        ctx.moveTo(x, y);
        ctx.quadraticCurveTo(
          x + Math.cos(angle) * length * 0.5,
          y + Math.sin(angle) * length * 0.5 + 10,
          x + Math.cos(angle) * length,
          y + Math.sin(angle) * length
        );
        ctx.stroke();
      }

      ctx.globalAlpha = 0.5;
      ctx.fillStyle = '#f5e6a8';
      ctx.font = 'italic 15px "Playfair Display", serif';
      ctx.textAlign = 'center';
      ctx.fillText('✦ Rê cọ để khám phá ✦', w / 2, h * 0.2);
      ctx.globalAlpha = 1;
    }

    function erase(e) {
      var rect = canvas.getBoundingClientRect();
      var x = e.clientX - rect.left;
      var y = e.clientY - rect.top;

      ctx.globalCompositeOperation = 'destination-out';

      var steps = lastX === null ? 0 : Math.max(1, Math.hypot(x - lastX, y - lastY) / 6 | 0);
      for (var i = 0; i <= steps; i++) {
        var t = steps ? i / steps : 0;
        var px = lastX === null ? x : lastX + (x - lastX) * t;
        var py = lastY === null ? y : lastY + (y - lastY) * t;

        var spot = ctx.createRadialGradient(px, py, 0, px, py, BRUSH_RADIUS);
        spot.addColorStop(0, 'rgba(0,0,0,1)');
        spot.addColorStop(0.6, 'rgba(0,0,0,.8)');
        spot.addColorStop(1, 'rgba(0,0,0,0)');
        ctx.fillStyle = spot;
        ctx.beginPath();
        ctx.arc(px, py, BRUSH_RADIUS, 0, 7);
        ctx.fill();
      }
      lastX = x;
      lastY = y;

      if (++moveCount % 12 === 0 && isMostlyCleared()) {
        cleared = true;
        canvas.style.opacity = 0;
        canvas.style.pointerEvents = 'none';
      }
    }

    function isMostlyCleared() {
      var pixels = ctx.getImageData(0, 0, canvas.width, canvas.height).data;
      var transparent = 0, total = 0;
      for (var k = 3; k < pixels.length; k += 160) {
        total++;
        if (pixels[k] < 50) transparent++;
      }
      return transparent / total > CLEAR_RATIO;
    }

    canvas.addEventListener('mousemove', erase);
    canvas.addEventListener('mouseleave', function () {
      lastX = lastY = null;
    });

    card.resetPaint = paintCover;
    paintCover();
    addEventListener('resize', paintCover);
  });
})();

;

/* ===== js/contact-form.js ===== */
(function () {
  var form = $('#contact-form');
  if (!form) return;

  var status = $('#form-status');
  var counter = $('#count');
  var EMAIL_PATTERN = /^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/;

  var validators = {
    name: function (value) {
      if (!value) return 'Vui lòng nhập tên của bạn.';
      if (value.length < 2) return 'Tên cần có ít nhất 2 ký tự.';
      return '';
    },
    email: function (value) {
      if (!value) return 'Vui lòng nhập email.';
      if (!EMAIL_PATTERN.test(value)) return 'Email chưa đúng định dạng (ví dụ: ten@gmail.com).';
      return '';
    },
    message: function (value) {
      if (!value) return 'Vui lòng nhập lời nhắn.';
      if (value.length < 10) return 'Lời nhắn cần có ít nhất 10 ký tự.';
      return '';
    }
  };

  function validateField(name) {
    var input = form.elements[name];
    var error = validators[name](input.value.trim());
    var box = input.closest('.field');

    $('.err', box).textContent = error;
    box.classList.toggle('invalid', !!error);
    box.classList.toggle('valid', !error);
    input.setAttribute('aria-invalid', !!error);
    return !error;
  }

  function showStatus(text, isError) {
    status.textContent = text;
    status.classList.toggle('error', !!isError);
  }

  Object.keys(validators).forEach(function (name) {
    var input = form.elements[name];
    input.addEventListener('blur', function () { validateField(name); });
    input.addEventListener('input', function () {
      if (input.closest('.field').classList.contains('invalid')) validateField(name);
    });
  });

  form.elements.message.addEventListener('input', function (e) {
    counter.textContent = e.target.value.length + '/' + e.target.maxLength;
  });

  form.addEventListener('submit', function (e) {
    e.preventDefault();

    var results = Object.keys(validators).map(validateField);
    if (results.indexOf(false) !== -1) {
      showStatus('Vui lòng sửa các ô báo lỗi rồi gửi lại.', true);
      var firstInvalid = $('.field.invalid input, .field.invalid textarea', form);
      if (firstInvalid) firstInvalid.focus();
      return;
    }

    var name = form.elements.name.value.trim();
    var email = form.elements.email.value.trim();
    var message = form.elements.message.value.trim();

    var subject = 'Liên hệ từ portfolio — ' + name;
    var body = message + '\n\n— ' + name + ' (' + email + ')';
    var mailto = 'mailto:' + form.dataset.mailto +
      '?subject=' + encodeURIComponent(subject) +
      '&body=' + encodeURIComponent(body);

    showStatus('✦ Cảm ơn ' + name + '! Ứng dụng email sẽ mở để bạn gửi lời nhắn.', false);
    form.reset();
    counter.textContent = '0/' + form.elements.message.maxLength;
    $$('.field', form).forEach(function (box) { box.classList.remove('valid', 'invalid'); });
    window.location.href = mailto;
  });
})();

;

/* ===== js/scroll-top.js ===== */
(function () {
  var button = $('#to-top');
  var SHOW_AFTER = 600;

  function updateVisibility() {
    button.classList.toggle('show', window.scrollY > SHOW_AFTER);
  }

  button.addEventListener('click', function () {
    window.scrollToY(0);
  });

  addEventListener('scroll', updateVisibility, { passive: true });
  updateVisibility();
})();

